// It never stores anything and never errors for bad city content: an invalid
// document is a result with valid=false and its issues, so an editor can show
// every problem.
func (r *mutationResolver) ValidateCity(ctx context.Context, config string) (*model.CityValidationResult, error) {
	if _, err := requireViewer(ctx); err != nil {
		return nil, err
	}
	cfg, err := engine.DecodeCityConfig([]byte(config))
	if err != nil {
		return &model.CityValidationResult{Valid: false, Publishable: false, Issues: []string{err.Error()}}, nil
	}
	if err := engine.ValidateCityConfigStructural(cfg); err != nil {
		return &model.CityValidationResult{Valid: false, Publishable: false, Issues: []string{err.Error()}}, nil
	}
	if err := engine.ValidateCityConfig(cfg); err != nil {
		return &model.CityValidationResult{Valid: true, Publishable: false, Issues: []string{err.Error()}}, nil
	}
	return &model.CityValidationResult{Valid: true, Publishable: true, Issues: []string{}}, nil
}

// Admin is the resolver for the admin field. It validates the key before the
// admin object exists, so no field on it can run unauthorized. Unknown ids are
// never revealed here: a wrong key is FORBIDDEN regardless of the target.
func (r *mutationResolver) Admin(ctx context.Context, key string) (*model.Admin, error) {
	if !r.adminKeyMatches(key) {
		if r.AdminKey == "" && !r.AllowUnauthenticatedAdmin {
			return nil, codedErr(codeForbidden, "admin operation disabled: set DELIVERY_ADMIN_API_KEY and pass it as admin(key)")
		}
		return nil, codedErr(codeForbidden, "admin operation requires a valid admin key")
	}
	return &model.Admin{}, nil
}

// Health is the resolver for the health field.
func (r *queryResolver) Health(ctx context.Context) (*model.Health, error) {
	return &model.Health{Status: "ok"}, nil
}

// Cities is the resolver for the cities field.
func (r *queryResolver) Cities(ctx context.Context) ([]*model.CityInfo, error) {
	catalog, err := r.catalogue()
	if err != nil {
		return nil, err
	}
	viewer := viewerID(ctx)
	list, err := catalog.ListFor(viewer)
	if err != nil {
		return nil, cityCodedError(err)
	}
	out := make([]*model.CityInfo, 0, len(list))
	for _, entry := range list {
		out = append(out, cityInfoFrom(entry, viewer))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, nil
}

// City is the resolver for the city field.
//
// An omitted id selects the default city. A missing city or another player's
// draft is null rather than an error, matching the schema's nullable field.
func (r *queryResolver) City(ctx context.Context, id *string) (*model.CityView, error) {
	catalog, err := r.catalogue()
	if err != nil {
		return nil, err
	}
	cityID := ""
	if id != nil {
		cityID = *id
	}
	if cityID == "" {
		cityID = catalog.DefaultID()
	}
	viewer := viewerID(ctx)
	entry, err := catalog.Get(cityID, viewer)
	if err != nil {
		if errors.Is(err, cityconfig.ErrNotFound) {
			return nil, nil
		}
		return nil, cityCodedError(err)
	}
	return cityViewForEntry(entry, viewer)
}

// CityConfig is the resolver for the cityConfig field.
//
// It returns the decoded, defaulted city document for a published city, a
// builtin, or the caller's own draft. Another player's draft is null, exactly
// like a missing city. The document is JSON-marshalled from the catalogue's
// CityConfig, so its keys are the ones players author.
func (r *queryResolver) CityConfig(ctx context.Context, id string) (*string, error) {
	catalog, err := r.catalogue()
	if err != nil {
		return nil, err
	}
	entry, err := catalog.Get(id, viewerID(ctx))
	if err != nil {
		if errors.Is(err, cityconfig.ErrNotFound) {
			return nil, nil
		}
		return nil, cityCodedError(err)
	}
	raw, err := json.Marshal(entry.Config)
	if err != nil {
		return nil, codedErr(codeInternal, fmt.Sprintf("encode city %q: %v", id, err))
	}
	text := string(raw)
	return &text, nil
}

// Sessions is the resolver for the sessions field.
func (r *queryResolver) Sessions(ctx context.Context, sort *model.SessionSort, limit *int, before *time.Time, cursor *string, mine *bool) ([]*model.SessionSummary, error) {
	opts := session.ListOptions{Limit: DefaultSessionListLimit}
	if sort != nil {
		opts.Sort = sessionSortFrom(*sort)
	}
	if limit != nil {
		if *limit < 1 {
			return nil, errBadInput("limit must be 1 or later")
		}
		opts.Limit = min(*limit, MaxSessionListLimit)
	}
	if cursor != nil {
		if before != nil {
			return nil, errBadInput("before and cursor cannot be combined")
		}
		cur, err := decodeSessionCursor(*cursor, opts.Sort)
		if err != nil {
			return nil, errBadInput(err.Error())
		}
		opts.Cursor = &cur
	}
	if before != nil {
		if opts.Sort != session.SortCreatedAt {
			return nil, errBadInput("before is only valid with sort CREATED_AT; use cursor")
		}
		if before.IsZero() {
			return nil, errBadInput("before must not be the zero time")
		}
		opts.Before = *before
	}
	if mine != nil && *mine {
		opts.AccountID = viewerID(ctx)
		if opts.AccountID == "" {
			return nil, codedErr(codeUnauthenticated, "mine needs a signed-in viewer")
		}
	}

	opts.Visible = func(s session.Summary) bool {
		visible, err := r.sessionCityVisible(ctx, s.CityID)
		return err == nil && visible
	}

	list := r.Mgr.List(opts)
	out := make([]*model.SessionSummary, 0, len(list))
	for _, s := range list {
		row := r.summaryView(ctx, s)
		row.Cursor = encodeSessionCursor(opts.Sort, row)
		out = append(out, row)
	}
	return out, nil
}

// MetricHistory is the resolver for the metricHistory field.
func (r *queryResolver) MetricHistory(ctx context.Context, metric model.AnalyticsMetric, ids []string, cityID *string, fromTick *int, toTick *int, maxPoints *int) ([]*model.ValueSeries, error) {
	if err := validateHistoryArgs(ids); err != nil {
		return nil, err
	}
	rows, err := r.Mgr.MetricHistory(ctx, session.Metric(metric), r.seriesRequest(ctx, ids, cityID, fromTick, toTick, maxPoints))
	if err != nil {
		slog.Error("delivery metricHistory", "metric", metric, "err", err)
		return nil, codedErr(codeInternal, "metric history is unavailable")
	}
	return seriesHistoryFrom(rows), nil
}

// Session is the resolver for the session field.
func (r *queryResolver) Session(ctx context.Context, id string) (*model.Snapshot, error) {
	sess, err := r.load(ctx, id)
	if err != nil {
		return nil, err
	}
	return r.snapshotView(ctx, sess.Snapshot()), nil
}

// TickSnapshots is the resolver for the tickSnapshots field.
//
// Reads the recorded per-tick log for one session. The session is resolved
// through the normal read path first, so an unknown save and another player's
// draft city are NOT_FOUND rather than an empty page. Tick bounds are
// inclusive and afterTick is an exclusive keyset cursor; both filters run in
// SQL so a page never decodes frames it will not return.
func (r *queryResolver) TickSnapshots(ctx context.Context, sessionID string, fromTick *int, toTick *int, afterTick *int, limit *int) ([]*model.TickSnapshot, error) {
	if _, err := r.load(ctx, sessionID); err != nil {
		return nil, err
	}
	q := session.TickSnapshotQuery{}
	if fromTick != nil {
		if *fromTick < 0 {
			return nil, errBadInput("fromTick must not be negative")
		}
		q.FromTick = int64(*fromTick)
	}
	if toTick != nil {
		if *toTick < 0 {
			return nil, errBadInput("toTick must not be negative")
		}
		q.ToTick = int64(*toTick)
	}
	if afterTick != nil {
		if *afterTick < 0 {
			return nil, errBadInput("afterTick must not be negative")
		}
		q.AfterTick = int64(*afterTick)
	}
	if q.FromTick > 0 && q.ToTick > 0 && q.FromTick > q.ToTick {
		return nil, errBadInput("fromTick must not be after toTick")
	}
	if limit != nil {
		if *limit < 1 {
			return nil, errBadInput("limit must be at least 1")
		}
		q.Limit = *limit
	}
	rows, err := r.Mgr.TickSnapshots(ctx, sessionID, q)
	if errors.Is(err, session.ErrSnapshotsDisabled) {
		// The log is optional infrastructure: a deployment with it off serves an
		// empty history instead of failing a read that has a valid answer.
		return []*model.TickSnapshot{}, nil
	}
	if err != nil {
		slog.Error("delivery tickSnapshots", "session", sessionID, "err", err)
		return nil, codedErr(codeInternal, "tick snapshots are unavailable")
	}
	return tickSnapshotsFrom(rows), nil
}

// CarView is the resolver for the carView field.
//
// A window of the city around one car. This is the cheap poll an agent or a
// client with a large map wants: it returns the local terrain, the cars in
// view and the nearby open orders instead of the whole snapshot.
func (r *queryResolver) CarView(ctx context.Context, id string, carID string, radius int) (*model.CarWindow, error) {
	sess, err := r.load(ctx, id)
	if err != nil {
		return nil, err
	}
	if radius < 0 {
		return nil, errBadInput("radius must be >= 0")
	}
	if radius > 10 {
		radius = 10
	}

	snap := sess.Snapshot()
	var car *session.CarView
	for i := range snap.Cars {
		if snap.Cars[i].ID == carID {
			car = &snap.Cars[i]
			break
		}
	}
	if car == nil {
		return nil, errNotFound("no car " + carID)
	}

	size := snap.City.GridSize
	x0, y0 := car.X-radius, car.Y-radius
	x1, y1 := car.X+radius, car.Y+radius
	if x0 < 0 {
		x0 = 0
	}
	if y0 < 0 {
		y0 = 0
	}
	if x1 > size-1 {
		x1 = size - 1
	}
	if y1 > size-1 {
		y1 = size - 1
	}

	rows := make([]string, 0, y1-y0+1)
	for y := y0; y <= y1; y++ {
		row := snap.City.Rows[y]
		// The row is a byte per tile in ASCII; slice by rune to stay safe if the
		// glyph set ever grows beyond ASCII.
		r := []rune(row)
		rows = append(rows, string(r[x0:min(x1+1, len(r))]))
	}

	visibleCars := make([]*model.CarView, 0, len(snap.Cars))
	for _, c := range snap.Cars {
		if c.X >= x0 && c.X <= x1 && c.Y >= y0 && c.Y <= y1 {
			visibleCars = append(visibleCars, carFrom(c))
		}
	}

	// Nearby orders: open ones whose kitchen or customer is inside the window.
	posOf := map[string]session.PointView{}
	for _, p := range snap.City.Kitchens {
		posOf[p.ID] = p
	}
	for _, p := range snap.City.Customers {
		posOf[p.ID] = p
	}
	inWindow := func(id string) bool {
		p, ok := posOf[id]
		if !ok {
			return false
		}
		return p.X >= x0 && p.X <= x1 && p.Y >= y0 && p.Y <= y1
	}

	nearby := make([]*model.OrderView, 0)
	for _, o := range snap.Orders {
		if o.State == "done" || o.State == "expired" {
			continue
		}
		if inWindow(o.KitchenID) || inWindow(o.CustomerID) {
			nearby = append(nearby, orderFrom(o))
		}
	}

	return &model.CarWindow{
		Car:          carFrom(*car),
		RowSpan:      y1 - y0 + 1,
		ColSpan:      x1 - x0 + 1,
		Rows:         rows,
		OriginX:      x0,
		OriginY:      y0,
		VisibleCars:  visibleCars,
		NearbyOrders: nearby,
	}, nil
}

// Events is the resolver for the events field.
func (r *queryResolver) Events(ctx context.Context, id string, sinceTick int, limit *int) (*model.EventFeed, error) {
	sess, err := r.load(ctx, id)
	if err != nil {
		return nil, err
	}
	cap := intPtrValue(limit, DefaultEventFeedLimit)
	if cap < 1 {
		return nil, errBadInput("limit must be 1 or later")
	}
	snap := sess.Snapshot()

	// The feed is oldest first and bounded by max_events; once a poller falls
	// behind the oldest retained row, the events it missed cannot be returned,
	// and saying so is the whole point of this shape.
	oldest := int(snap.Tick)
	feed := &model.EventFeed{Capacity: snap.EventCapacity, Events: []*model.EventView{}}
	for _, e := range snap.Events {
		if int(e.Tick) >= sinceTick {
			feed.Events = append(feed.Events, eventFrom(e))
		}
	}
	if len(snap.Events) > 0 {
		oldest = int(snap.Events[0].Tick)
	}
	feed.OldestTick = oldest
	// Only a wrapped ring has dropped events. Before it wraps, ticks before
	// the first event are quiet, not lost, and reporting them as truncated
	// makes every client resync for nothing.
	feed.Truncated = sinceTick < oldest && snap.EventCapacity > 0 && len(snap.Events) >= snap.EventCapacity

	if cap > snap.EventCapacity && snap.EventCapacity > 0 {
		cap = snap.EventCapacity
	}
	if len(feed.Events) > cap {
		// Clipping to the caller's own limit is not a ring gap: the events
		// exist and a smaller sinceTick or a larger limit returns them.
		feed.Events = feed.Events[len(feed.Events)-cap:]
	}
	return feed, nil
}

// CanPlaySession is the resolver for the canPlaySession field.
//
// It answers whether this caller may change the session (and so is its player
// rather than a spectator): the creator by owner token or owning login, or
// anyone for a session created before owner tokens. It never errors: an
// unknown or malformed id is false, like any other unauthorized caller.
func (r *queryResolver) CanPlaySession(ctx context.Context, id string, ownerToken *string) (bool, error) {
	if !session.ValidID(id) {
		return false, nil
	}
	sess, err := r.Mgr.GetOrLoad(id)
	if err != nil {
		return false, nil
	}
	// A credential holder knows the session exists; the city gate must not
	// contradict the mutations it can already perform on a draft city.
	return sess.CanPlay(actor(ctx, ownerToken)), nil
}

// Orders is the resolver for the orders field.
func (r *snapshotResolver) Orders(ctx context.Context, obj *model.Snapshot, state []model.OrderState, carID *string, sinceTick *int, includeFinished *bool, limit *int) ([]*model.OrderView, error) {
	if limit != nil && *limit < 1 {
		return nil, errBadInput("limit must be 1 or later")
	}
	if sinceTick != nil && *sinceTick < 0 {
		return nil, errBadInput("sinceTick must not be negative")
	}
	cap := intPtrValue(limit, DefaultOrderFilterLimit)
	if cap > MaxOrderFilterLimit {
		cap = MaxOrderFilterLimit
	}
	keepFinished := includeFinished == nil || *includeFinished

	wantState := make(map[model.OrderState]bool, len(state))
	for _, s := range state {
		wantState[s] = true
	}

	out := make([]*model.OrderView, 0, len(obj.Orders))
	for _, o := range obj.Orders {
		if !keepFinished && (o.State == model.OrderStateDone || o.State == model.OrderStateExpired) {
			continue
		}
		if len(wantState) > 0 && !wantState[o.State] {
			continue
		}
		if carID != nil && (o.AssignedCar == nil || *o.AssignedCar != *carID) {
			continue
		}
		if sinceTick != nil && o.CreatedTick < *sinceTick {
			continue
		}
		out = append(out, o)
		if len(out) == cap {
			break
		}
	}
	return out, nil
}

// OpenOrders is the resolver for the openOrders field.
//
// The prebuilt list is used when present; a hand-built snapshot without one
// falls back to filtering the full list, so tests and internal callers do not
// have to populate both.
func (r *snapshotResolver) OpenOrders(ctx context.Context, obj *model.Snapshot) ([]*model.OrderView, error) {
	if obj.OpenOrders != nil {
		return obj.OpenOrders, nil
	}
	out := make([]*model.OrderView, 0, len(obj.Orders))
	for _, o := range obj.Orders {
		if o.State == model.OrderStateDone || o.State == model.OrderStateExpired {
			continue
		}
		out = append(out, o)
	}
	return out, nil
}

// Session is the resolver for the session field.
//
// It returns a channel immediately and does the waiting in a goroutine, which
// is what gqlgen expects of a subscription: the transport reads frames off the
// channel and blocks on it, so nothing here may block before returning.
//
// The first value is sent eagerly. A subscriber that waited for the next tick
// would show an empty screen for a full tick on a running clock — and forever
// on a paused one, which is the default state.
func (r *subscriptionResolver) Session(ctx context.Context, id string) (<-chan *model.Snapshot, error) {
	sess, err := r.load(ctx, id)
	if err != nil {
		return nil, err
	}

	// Buffered so the first send (the eager snapshot) cannot block before the
	// transport has started reading.
	out := make(chan *model.Snapshot, 1)
	watch := sess.Watch()

	go func() {
		defer close(out)
		defer sess.Unwatch(watch)

		for {
			snap := sess.StreamSnapshot()
			select {
			case out <- r.snapshotView(ctx, snap):
			case <-ctx.Done():
				return
			}
			// Wait for the next change. NextContext also returns false when the
			// client goes away, so a paused session cannot strand this
			// goroutine (and its watcher) after a disconnect.
			if !watch.NextContext(ctx) {
				return
			}
		}
	}()

	return out, nil
}

// Admin returns generated.AdminResolver implementation.
func (r *Resolver) Admin() generated.AdminResolver { return &adminResolver{r} }

// LedgerView returns generated.LedgerViewResolver implementation.
func (r *Resolver) LedgerView() generated.LedgerViewResolver { return &ledgerViewResolver{r} }

// Mutation returns generated.MutationResolver implementation.
func (r *Resolver) Mutation() generated.MutationResolver { return &mutationResolver{r} }

// Query returns generated.QueryResolver implementation.
func (r *Resolver) Query() generated.QueryResolver { return &queryResolver{r} }

// Snapshot returns generated.SnapshotResolver implementation.
func (r *Resolver) Snapshot() generated.SnapshotResolver { return &snapshotResolver{r} }

// Subscription returns generated.SubscriptionResolver implementation.
func (r *Resolver) Subscription() generated.SubscriptionResolver { return &subscriptionResolver{r} }

type adminResolver struct{ *Resolver }
type ledgerViewResolver struct{ *Resolver }
type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
type snapshotResolver struct{ *Resolver }
type subscriptionResolver struct{ *Resolver }
